<script setup>
import {useTableLayout} from '../../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()



import {computed, onMounted, ref, watch} from 'vue'
import {useRoute, useRouter} from 'vue-router'
import {api, post} from '../api.js'
import {toast} from '../../shared/composables/toast.js'


import PageHeader from '../../shared/components/PageHeader.vue'
import HelpTip from '../../shared/components/HelpTip.vue'
import StatePanel from '../../shared/components/StatePanel.vue'
import ReleaseRulesSettings from '../components/ReleaseRulesSettings.vue'
const showRules=ref(false)
const route=useRoute(),router=useRouter(),overview=ref({connections:[]}),selected=ref(''),account=ref(''),password=ref(''),busy=ref(false),me=ref({})
const hint=ref(''),hintLoading=ref(false),hintError=ref('')
const pageLoading=ref(true),loadError=ref('')
let hintRequest=0
const connection=computed(()=>overview.value.connections.find(c=>c.name===selected.value))
const canReuse=computed(()=>connection.value?.credential_saved!==false&&!!connection.value?.account&&connection.value.account===account.value&&connection.value.auth_status!=='needs_verification')
const authLabel=c=>({connected:'已验证 · 会话可复用',saved:'凭据已保存 · 按需连接',needs_verification:'认证失效 · 请重新验证',unverified:'未验证本人账号'})[c.auth_status]||(c.authorized?'已验证':'未验证本人账号')
const target=()=>typeof route.query.return_to==='string'&&/^\/(?:work(?:\/\d+)?)?(?:\?|$)/.test(route.query.return_to)?route.query.return_to:''
function fillAccount(){account.value=connection.value?.account||''}
async function loadHint(){const name=selected.value,request=++hintRequest;hint.value='';hintError.value='';hintLoading.value=true;try{if(!name)return;const result=await api('research/connections/'+encodeURIComponent(name)+'/account-hint');if(request!==hintRequest||name!==selected.value)return;hint.value=result.account||'';if(!account.value)account.value=hint.value}catch(e){if(request===hintRequest)hintError.value=e.message}finally{if(request===hintRequest)hintLoading.value=false}}
async function load(){overview.value=await api('research/overview');if(!selected.value)selected.value=route.query.connection||overview.value.connections[0]?.name||'';fillAccount()}
async function save(){if(busy.value)return;busy.value=true;let success=false;try{await post('research/connections/'+encodeURIComponent(selected.value)+'/authorize',{account:account.value,password:password.value});await load();success=true;toast('已验证本人来源账号，后续复用有效会话','success')}catch(e){toast(e.message,'error');await load().catch(()=>{})}finally{password.value='';busy.value=false}if(success&&target())await router.replace(target())}
async function remove(name){if(busy.value)return;busy.value=true;try{await api('research/connections/'+encodeURIComponent(name)+'/authorize',{method:'DELETE'});await load();toast('已移除本人凭据','success')}catch(e){toast(e.message,'error')}finally{busy.value=false}}
watch(selected,()=>{password.value='';fillAccount();loadHint()})
async function initialize(){pageLoading.value=true;loadError.value='';try{me.value=await api('/api/me');await load()}catch(e){loadError.value=e.message;toast(e.message,'error')}finally{pageLoading.value=false}}
onMounted(initialize)

import OptionPicker from '../../shared/components/OptionPicker.vue'

import {ref as _viewRef} from 'vue'
const _view1=_viewRef([])



import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Button,Empty,EmptyDescription,EmptyHeader,Field,FieldLabel,Input,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'
</script>
<template><PageHeader title="工作台设置" help="公共读取沿用管理员已配置的连接。人员同步只建立身份关联，不包含密码，也不等于授权；本人凭据加密保存，有效会话复用，回写失败不自动重放。"><template #actions><Button v-if="target()" @click="router.push(target())" variant="ghost" size="default" type="button" :disabled="(busy)">返回原工作项</Button></template></PageHeader><StatePanel v-if="pageLoading" loading title="正在读取来源账号…"/><StatePanel v-else-if="loadError" error title="来源账号读取失败" :message="loadError"><Button @click="initialize" variant="outline" size="default" type="button">重试</Button></StatePanel><StatePanel v-else-if="!overview.connections.length" title="尚未配置来源连接" message="请由管理员在资源中心添加需求平台连接，配置后即可验证本人账号。"/><template v-else><section class="r-surface source-account-form"><div class="account-fields"><Field class="connection-field"><FieldLabel as="div"><span>来源连接</span></FieldLabel><OptionPicker v-model="selected" :options="overview.connections.map(c=>({value:c.name,label:c.name}))" :style="{width:'100%',maxWidth:'100%'}" :disabled="busy"/></Field><Field ><FieldLabel as="div"><span>本人来源账号</span></FieldLabel><Input v-model="account" :disabled="busy" v-bind="{&quot;autocomplete&quot;:&quot;username&quot;,&quot;aria-describedby&quot;:&quot;source-account-hint&quot;}"/></Field><Field ><FieldLabel as="div"><span>本人来源密码</span></FieldLabel><Input v-model="password" type="password" :disabled="busy" :placeholder="canReuse?'已保存，留空可检查连接':'首次验证或认证失效时填写'" v-bind="{&quot;autocomplete&quot;:&quot;off&quot;}"/></Field></div><p id="source-account-hint" :class="{'r-error':hintError}" aria-live="polite" class="account-hint r-muted">{{hintLoading?'正在读取本人关联…':hint?'已关联账号：'+hint+'；首次使用仍需验证。':hintError||'未关联人员时可填写本人来源账号。'}}</p><div class="account-footer"><span class="r-muted">{{connection?.public_read_configured?'公共读取已配置，无需重复填写。':'公共读取连接由管理员配置。'}} {{authLabel(connection||{})}}</span><Button @click="save" variant="default" size="default" type="button" :disabled="(!selected||!account||(!password&amp;&amp;!canReuse)||me.auth_enabled===false)||(busy)"><Spinner v-if="busy"/>{{target()?'验证并返回原工作项':canReuse&&!password?'检查本人连接':'验证并保存本人账号'}}</Button></div><p v-if="me.auth_enabled===false" class="r-muted">当前未启用平台登录，尚不能验证个人来源账号或回写 Bug。</p></section><div class="r-table"><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:616}).y?({x:616}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:616}).x||({x:616}).minWidth||616)+'px'}"><TableHeader class="bg-muted/50"><TableRow><TableHead :style="{width:(180)+'px'}">连接</TableHead><TableHead :style="{width:(140)+'px'}">本人账号</TableHead><TableHead :style="{width:(120)+'px'}">状态</TableHead><TableHead :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-muted':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-muted':''" :style="{width:(176)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((overview.connections)||[]).map((c,rowIndex)=>({...c,__rowKey:c.name}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{c.name}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{c.account||'—'}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{authLabel(c)}}</div></template></div></TableCell><TableCell class="align-top" :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div><Button v-if="c.credential_saved||c.authorized||c.account" @click="remove(c.name)" variant="ghost" size="sm" type="button" :disabled="(busy)"><Spinner v-if="busy"/>移除本人凭据</Button></div></template></div></TableCell></TableRow></template><TableRow v-if="!(((overview.connections)||[]).map((c,rowIndex)=>({...c,__rowKey:c.name}))||[]).length"><TableCell :colspan="4"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div></template><Accordion v-if="me.role==='admin'&&selected" class="r-surface research-release-rules platform-collapse" type="multiple" :model-value="(_view1||[]).map(String)" @update:model-value="keys=>{_view1=keys;if(keys.length)showRules=true}"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>上线识别规则（管理员）</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view1||[]).map(String).includes(String(&quot;panel&quot;)))"><ReleaseRulesSettings v-if="showRules" :key="selected" :connection="selected"/></AccordionContent></AccordionItem></Accordion></template>
<style scoped>.account-fields{display:grid;grid-template-columns:minmax(180px,.8fr) repeat(2,minmax(200px,1fr));gap:16px;align-items:start}.account-fields>label{display:flex;flex-direction:column;gap:8px;min-width:0;font-size:.875rem}.account-hint{margin:10px 0 0;line-height:1.6;overflow-wrap:anywhere}.account-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-top:16px;padding-top:12px;border-top:1px solid var(--border)}.research-release-rules{margin-top:14px}
@media(max-width:1000px){.account-fields{grid-template-columns:repeat(2,minmax(0,1fr))}.connection-field{grid-column:1/-1}}
@media(max-width:600px){.account-fields{grid-template-columns:minmax(0,1fr)}}</style>
